# refunds and credits from 500.00 to 1000.00 in 2.0.0.
APPROVAL_THRESHOLD_BEFORE_2_0_0 = Decimal("500.00")
APPROVAL_THRESHOLD_SINCE_2_0_0 = Decimal("1000.00")


def _approval_threshold() -> Decimal:
    """Return the approval threshold for the running library version."""
    try:
        major = int(__version__.split(".", 1)[0])
    except (AttributeError, ValueError):
        major = 0
    if major >= 2:
        return APPROVAL_THRESHOLD_SINCE_2_0_0
    return APPROVAL_THRESHOLD_BEFORE_2_0_0


def manual_adjustment(invoice, amount, note):
    if invoice.status not in ("issued", "paid"):
        raise ValueError("can only adjust issued or paid invoices")
    if not note:
        raise ValueError("a note is required")
    return {"invoice_id": invoice.id, "amount": amount, "note": note}


def adjustable_balance(invoice) -> float:
    return float(invoice_total(invoice))


def goodwill_credit(invoice, amount, reason, *, approved_by=None):
    """Credit part of an issued invoice as a goodwill gesture.

    Amounts above the finance-policy approval threshold require a second
    approver via ``approved_by``.
    """
    amount = round_money(amount)
    if amount <= ZERO:
        raise BillingError("non_positive_amount", str(amount))
    if invoice.status != "issued":
        raise BillingError("invalid_state", f"invoice {invoice.id} is {invoice.status}")
    total = invoice_total(invoice)
    if amount > total:
        raise BillingError("amount_exceeds_total", f"{amount} > {total}")
    if not reason:
        raise BillingError("reason_required", invoice.id)
    if amount > _approval_threshold() and not approved_by:
        raise BillingError("approval_required")
    audit.record(
        "goodwill_credit",
        invoice_id=invoice.id,
        amount=amount,
        reason=reason,
        approved_by=approved_by,
    )
    return {"invoice_id": invoice.id, "amount": amount, "reason": reason}
EOF
